/**
 * Per-wave electrode look, from the Robotron 2084 ROM: wave-init ($2A21) picks one
 * of 9 shapes ($3B05 descriptors) from a 10-wave table at $2A4B, so the look repeats
 * every 10 waves. Rows are the shape's resting frame, one char per pixel ('#' lit).
 * Every lit pixel draws in palette entry `entry`, which the ROM colour-cycles
 * (ColorCycles.ts); checked frame by frame in MAME (robotron-re
 * tools/electrode_probe.lua). Waves ending in 7 or 9 never have electrodes.
 *
 * Generated by robotron-re tools/gen_electrodes_ts.py — do not hand-edit.
 */

export interface ElectrodeLook {
    /** palette entry the electrodes draw in (row 1 of the $2A4B table) */
    entry: number;
    rows: string[];
}

const LOOKS: ElectrodeLook[] = [
    // waves 1, 11, ...: shape $3B05
    {
        entry: 0xF,
        rows: [
            '....#.....',
            '.#..#..#..',
            '..#.#.#...',
            '...###....',
            '#########.',
            '...###....',
            '..#.#.#...',
            '.#..#..#..',
            '....#.....',
        ],
    },
    // waves 2, 12, ...: shape $3B15
    {
        entry: 0xE,
        rows: [
            '....#.....',
            '.#.#.#.#..',
            '..#.#.#...',
            '.#.#.#.#..',
            '#.#...#.#.',
            '.#.#.#.#..',
            '..#.#.#...',
            '.#.#.#.#..',
            '....#.....',
        ],
    },
    // waves 3, 13, ...: shape $3B25
    {
        entry: 0xB,
        rows: [
            '#########.',
            '#########.',
            '#########.',
            '#########.',
            '#########.',
            '#########.',
            '#########.',
            '#########.',
            '#########.',
        ],
    },
    // waves 4, 14, ...: shape $3B35
    {
        entry: 0xD,
        rows: [
            '........#.',
            '.......##.',
            '......###.',
            '.....####.',
            '....#####.',
            '...######.',
            '..#######.',
            '.########.',
            '#########.',
        ],
    },
    // waves 5, 15, ...: shape $3B45
    {
        entry: 0xE,
        rows: [
            '#####.',
            '#####.',
            '#####.',
            '#####.',
            '#####.',
            '#####.',
            '#####.',
            '#####.',
            '#####.',
        ],
    },
    // waves 6, 16, ...: shape $3B55
    {
        entry: 0xF,
        rows: [
            '....#.....',
            '...###....',
            '..#####...',
            '.#######..',
            '#########.',
            '.#######..',
            '..#####...',
            '...###....',
            '....#.....',
        ],
    },
    // waves 7, 17, ...: shape $3B75
    {
        entry: 0x1,
        rows: [
            '....#.....',
            '.#######..',
            '.###.###..',
            '.##...##..',
            '##.....##.',
            '.##...##..',
            '.###.###..',
            '.#######..',
            '....#.....',
        ],
    },
    // waves 8, 18, ...: shape $3B85
    {
        entry: 0xB,
        rows: [
            '#########.',
            '#.......#.',
            '#.#####.#.',
            '#.#...#.#.',
            '#.#.#.#.#.',
            '#.###.#.#.',
            '#.....#.#.',
            '#######.#.',
            '........#.',
            '.########.',
        ],
    },
    // waves 9, 19, ...: shape $3B05
    {
        entry: 0xD,
        rows: [
            '....#.....',
            '.#..#..#..',
            '..#.#.#...',
            '...###....',
            '#########.',
            '...###....',
            '..#.#.#...',
            '.#..#..#..',
            '....#.....',
        ],
    },
    // waves 10, 20, ...: shape $3B65
    {
        entry: 0xA,
        rows: [
            '#################.',
            '#...#...#...#.#.#.',
            '###.#.#.#.#.#.#.#.',
            '#...#.#.#...#...#.',
            '#.###.#.#.#.###.#.',
            '#...#...#...###.#.',
            '#################.',
        ],
    },
];

/** Look for a 1-based wave. */
export function electrodeLook(wave: number): ElectrodeLook {
    return LOOKS[(Math.max(1, wave) - 1) % 10];
}
